12	/**
13	 * Azione di riga che apre la {@see AssetManager} per il record (digital-hub #16).
14	 *
15	 * Generica: usabile nella tabella di qualunque resource il cui modello usa il
16	 * trait HasAssets. L'URL è costruito dalla coppia polimorfica del record
17	 * (morph alias + chiave); perché l'alias sia leggibile nell'URL il template
18	 * deve registrare il record in una morph map (es. `Relation::morphMap`).
19	 */
20	class ManageAssetsAction
21	{
22	    public static function make(string $name = 'manageAssets'): Action
23	    {
24	        return Action::make($name)
25	            ->label(__('digital-hub::assets.manage'))
26	            ->icon(Heroicon::OutlinedFolderOpen)
27	            ->url(fn (Model $record): string => AssetManager::getUrl([
28	                'ownerType' => $record->getMorphClass(),
29	                'owner' => $record->getKey(),
30	            ]));
31	    }
32	}
